<?php
declare(strict_types=1);
namespace App\Services;
use App\Core\Validator;
use App\Repositories\StudentRepository;
use DomainException;

final class StudentCsvService{
public const HEADERS=['student_name','registration_no','date_of_admission','class_name','monthly_fee','discount_type','discount_value','mobile','date_of_birth','gender','nationality','identification_mark','blood_group','disease','birth_form_nic','caste','previous_school','previous_board','previous_id_board_roll','board_registration_no','board_roll_no','additional_note','orphan_student','osc','religion','family','total_siblings','address','guardian_name','guardian_nic','guardian_mobile','father_name','father_education','father_nic','father_mobile','father_occupation','father_profession','father_income','mother_name','mother_education','mother_nic','mother_mobile','mother_occupation','mother_profession','mother_income','status'];
private const MAP=['student_name'=>'studentname','registration_no'=>'reg','date_of_admission'=>'doa','monthly_fee'=>'student_fee','discount_value'=>'discount','mobile'=>'Gphone','date_of_birth'=>'dob','identification_mark'=>'idmark','blood_group'=>'blood','disease'=>'desease','birth_form_nic'=>'scnic','caste'=>'cast','previous_school'=>'pr','previous_id_board_roll'=>'previousid','additional_note'=>'additionalinfo','orphan_student'=>'os','total_siblings'=>'noc','father_name'=>'fname','father_education'=>'fedu','father_nic'=>'fcnic','father_mobile'=>'fmobile','father_occupation'=>'fo','father_profession'=>'fp','father_income'=>'fi','mother_name'=>'mname','mother_education'=>'medu','mother_nic'=>'mcnic','mother_mobile'=>'mmobile','mother_occupation'=>'mo','mother_profession'=>'mp','mother_income'=>'mi'];
public function __construct(private readonly StudentRepository$r){}
public static function example(array$classes):string{$row=array_fill_keys(self::HEADERS,'');$row=array_replace($row,['student_name'=>'Ayesha Khan','registration_no'=>'STU-001','date_of_admission'=>date('Y-m-d'),'class_name'=>(string)($classes[0]['name']??'Grade 1'),'monthly_fee'=>'5000','discount_type'=>'percentage','discount_value'=>'10','mobile'=>'03001234567','date_of_birth'=>'2012-05-14','gender'=>'Female','nationality'=>'Pakistani','identification_mark'=>'None','blood_group'=>'B+','disease'=>'None','birth_form_nic'=>'61101-1234567-8','previous_school'=>'Example School','additional_note'=>'Example row - replace or remove','orphan_student'=>'No','osc'=>'No','religion'=>'Islam','family'=>'Khan Family','total_siblings'=>'2','address'=>'House 1, Main Road','guardian_name'=>'Imran Khan','guardian_nic'=>'61101-1234567-1','guardian_mobile'=>'03001234567','father_name'=>'Imran Khan','father_education'=>'Graduate','father_nic'=>'61101-1234567-1','father_mobile'=>'03001234567','father_occupation'=>'Business','father_profession'=>'Retailer','father_income'=>'100000','mother_name'=>'Sara Khan','mother_education'=>'Graduate','mother_nic'=>'61101-7654321-2','mother_mobile'=>'03007654321','mother_occupation'=>'Homemaker','mother_income'=>'0','status'=>'active']);$s=fopen('php://temp','r+');fputcsv($s,self::HEADERS);fputcsv($s,array_values($row));rewind($s);return(string)stream_get_contents($s);}
public function import(array$file,int$i):int{$error=(int)($file['error']??UPLOAD_ERR_NO_FILE);$path=(string)($file['tmp_name']??'');if($error!==UPLOAD_ERR_OK)throw new DomainException($error===UPLOAD_ERR_NO_FILE?'Choose a CSV file to import.':'The CSV upload failed. Please try again.');if(strtolower(pathinfo((string)($file['name']??''),PATHINFO_EXTENSION))!=='csv')throw new DomainException('The uploaded file must have a .csv extension.');$size=is_file($path)?filesize($path):false;if($size===false||$size<=0||$size>2097152)throw new DomainException('The CSV must not be empty or larger than 2MB.');$h=fopen($path,'rb');if(!$h)throw new DomainException('The CSV could not be read.');$header=fgetcsv($h);if($header&&isset($header[0]))$header[0]=preg_replace('/^\xEF\xBB\xBF/','',(string)$header[0]);if($header!==self::HEADERS){fclose($h);throw new DomainException('CSV columns do not match the template. Download a fresh example CSV and keep its header row unchanged.');}$classMap=[];foreach($this->r->classesForImport($i)as$c)$classMap[mb_strtolower(trim((string)$c['name']))]=(int)$c['id'];$existing=array_fill_keys(array_map('mb_strtolower',$this->r->registrations($i)),true);$seen=[];$rows=[];$line=1;while(($values=fgetcsv($h))!==false){$line++;if(count($values)===1&&trim((string)$values[0])==='')continue;if(count($values)!==count(self::HEADERS)){fclose($h);throw new DomainException("Row {$line}: expected ".count(self::HEADERS).' columns, found '.count($values).'.');}$row=array_combine(self::HEADERS,array_map(static fn($v)=>trim((string)$v),$values));if($message=$this->rowError($row,$line,$classMap,$existing,$seen)){fclose($h);throw new DomainException($message);}$seen[mb_strtolower($row['registration_no'])]=true;$input=$row;foreach(self::MAP as$csv=>$form)$input[$form]=$row[$csv];$input['class']=$classMap[mb_strtolower($row['class_name'])];$mapped=(new StudentService($this->r))->data($input,$i);$mapped['status']=$row['status']?:'active';$mapped['created_at']=$mapped['updated_at'];$rows[]=$mapped;if(count($rows)>1000){fclose($h);throw new DomainException('A single CSV can contain at most 1,000 students.');}}fclose($h);if(!$rows)throw new DomainException('The CSV contains no student rows.');return$this->r->createMany($rows);}
private function rowError(array$r,int$line,array$classes,array$existing,array$seen):?string{$v=new Validator();if(!$v->validate($r,['student_name'=>'required|max:160','registration_no'=>'required|max:80','date_of_admission'=>'required|date','monthly_fee'=>'numeric|min:0','discount_type'=>'required|in:percentage,fixed','discount_value'=>'required|numeric|min:0','date_of_birth'=>'date','total_siblings'=>'integer|min:0','father_income'=>'numeric|min:0','mother_income'=>'numeric|min:0','status'=>'in:active,inactive'])){$errors=$v->errors();$first=reset($errors);return"Row {$line}: ".($first[0]??'Invalid data.');}if(!isset($classes[mb_strtolower($r['class_name'])]))return"Row {$line}: class '{$r['class_name']}' does not exist for this institute.";if($r['discount_type']==='percentage'&&(float)$r['discount_value']>100)return"Row {$line}: percentage discount cannot exceed 100.";$key=mb_strtolower($r['registration_no']);if(isset($existing[$key]))return"Row {$line}: registration number '{$r['registration_no']}' already exists.";if(isset($seen[$key]))return"Row {$line}: registration number '{$r['registration_no']}' is duplicated in the CSV.";return null;}
}
